import React, { useState } from 'react';
import { useAuth } from '../auth/AuthContext';

export default function MyBorrowings() {
  const { user } = useAuth();

  // ข้อมูลจำลองรายการยืม
  const [borrowings, setBorrowings] = useState([
    {
      id: 1,
      equipmentName: "Sony Mirrorless Camera Alpha 6400",
      quantity: 1,
      borrowDate: "2026-11-15",
      returnDate: "2026-11-18",
      purpose: "ถ่ายโปรเจกต์วิดีโอส่งอาจารย์",
      status: "รออนุมัติ"
    },
    {
      id: 2,
      equipmentName: "Shure SM58 Vocal Microphone",
      quantity: 2,
      borrowDate: "2026-11-10",
      returnDate: "2026-11-12",
      purpose: "อัดเสียงพอดแคสต์กิจกรรมคณะ",
      status: "กำลังใช้งาน"
    }
  ]);

  // State สำหรับจัดการ Modal เขียนรีวิว
  const [reviewModalOpen, setReviewModalOpen] = useState(false);
  const [selectedItemForReview, setSelectedItemForReview] = useState(null);
  const [rating, setRating] = useState(5);
  const [comment, setComment] = useState('');

  // ฟังก์ชันยกเลิกคำขอ
  const handleCancel = (id) => {
    setBorrowings(borrowings.filter(item => item.id !== id));
  };

  // ฟังก์ชันกดคืนอุปกรณ์
  const handleReturn = (id) => {
    setBorrowings(borrowings.map(item => 
      item.id === id ? { ...item, status: 'คืนสำเร็จ' } : item
    ));
  };

  // ส่งรีวิว
  const handleSubmitReview = (e) => {
    e.preventDefault();
    if (!comment.trim()) return;

    // ตรงนี้สามารถบันทึกรีวิวลง localStorage หรือส่งไปแชร์ร่วมกันได้
    alert(`ส่งรีวิวสำหรับ "${selectedItemForReview.equipmentName}" เรียบร้อยแล้ว! ข้อมูลจะไปแสดงที่หน้าข้อมูลอุปกรณ์`);
    setReviewModalOpen(false);
    setComment('');
  };

  return (
    <div style={{ maxWidth: '900px', margin: '30px auto', padding: '0 20px' }}>
      <h2 style={{ color: '#1E293B', marginBottom: '6px', fontSize: '22px' }}>📦 ประวัติการขอยืมอุปกรณ์ของฉัน</h2>
      <p style={{ color: '#64748B', fontSize: '14px', marginBottom: '24px' }}>ตรวจสอบสถานะคำขอยืมและกำหนดคืนอุปกรณ์ของคุณ</p>

      {borrowings.length === 0 ? (
        <div style={{ textAlign: 'center', padding: '40px', background: '#FFFFFF', borderRadius: '12px', border: '1px solid #E2E8F0', color: '#64748B' }}>
          ยังไม่มีประวัติการขอยืมอุปกรณ์
        </div>
      ) : (
        <div style={{ display: 'flex', flexDirection: 'column', gap: '16px' }}>
          {borrowings.map((item) => (
            <div key={item.id} style={{
              background: '#FFFFFF',
              padding: '20px',
              borderRadius: '12px',
              border: '1px solid #E2E8F0',
              boxShadow: '0 2px 10px rgba(0,0,0,0.02)',
              display: 'flex',
              justifyContent: 'space-between',
              alignItems: 'center',
              flexWrap: 'wrap',
              gap: '16px'
            }}>
              <div style={{ flex: 1, minWidth: '280px' }}>
                <div style={{ display: 'flex', alignItems: 'center', gap: '10px', marginBottom: '6px' }}>
                  <h4 style={{ margin: 0, color: '#1E293B', fontSize: '16px' }}>{item.equipmentName}</h4>
                  <span style={{
                    background: item.status === 'รออนุมัติ' ? '#FEF3C7' : item.status === 'กำลังใช้งาน' ? '#DBEAFE' : '#DCFCE7',
                    color: item.status === 'รออนุมัติ' ? '#D97706' : item.status === 'กำลังใช้งาน' ? '#1D4ED8' : '#15803D',
                    padding: '4px 10px',
                    borderRadius: '20px',
                    fontSize: '12px',
                    fontWeight: '600'
                  }}>
                    {item.status}
                  </span>
                </div>
                <p style={{ margin: '0 0 4px 0', fontSize: '13px', color: '#475569' }}>📌 จำนวนที่ยืม: {item.quantity} ชิ้น</p>
                <p style={{ margin: '0 0 4px 0', fontSize: '13px', color: '#475569' }}>📅 วันที่ยืม - คืน: {item.borrowDate} ถึง {item.returnDate}</p>
                <p style={{ margin: 0, fontSize: '13px', color: '#64748B' }}>💬 วัตถุประสงค์: {item.purpose}</p>
              </div>

              {/* ปุ่มจัดการตามสถานะ */}
              <div>
                {item.status === 'รออนุมัติ' && (
                  <button 
                    onClick={() => handleCancel(item.id)}
                    style={{ background: '#FEE2E2', color: '#DC2626', border: 'none', padding: '8px 14px', borderRadius: '8px', fontWeight: '600', cursor: 'pointer', fontSize: '13px' }}
                  >
                    ยกเลิกคำขอ
                  </button>
                )}

                {item.status === 'กำลังใช้งาน' && (
                  <button 
                    onClick={() => handleReturn(item.id)}
                    style={{ background: '#2563EB', color: '#FFFFFF', border: 'none', padding: '8px 14px', borderRadius: '8px', fontWeight: '600', cursor: 'pointer', fontSize: '13px' }}
                  >
                    🔄 คืนอุปกรณ์
                  </button>
                )}

                {item.status === 'คืนสำเร็จ' && (
                  <button 
                    onClick={() => {
                      setSelectedItemForReview(item);
                      setReviewModalOpen(true);
                    }}
                    style={{ background: '#16A34A', color: '#FFFFFF', border: 'none', padding: '8px 14px', borderRadius: '8px', fontWeight: '600', cursor: 'pointer', fontSize: '13px' }}
                  >
                    ⭐ เขียนรีวิวอุปกรณ์
                  </button>
                )}
              </div>
            </div>
          ))}
        </div>
      )}

      {/* Modal เขียนรีวิว */}
      {reviewModalOpen && (
        <div style={{ position: 'fixed', top: 0, left: 0, width: '100%', height: '100%', background: 'rgba(0,0,0,0.5)', display: 'flex', justifyContent: 'center', alignItems: 'center', zIndex: 1000, padding: '20px' }}>
          <div style={{ background: '#FFFFFF', padding: '24px', borderRadius: '16px', maxWidth: '450px', width: '100%', boxShadow: '0 10px 25px rgba(0,0,0,0.1)' }}>
            <h3 style={{ margin: '0 0 10px 0', color: '#1E293B', fontSize: '18px' }}>✍️ เขียนรีวิว: {selectedItemForReview?.equipmentName}</h3>

            <form onSubmit={handleSubmitReview}>
              <div style={{ marginBottom: '14px' }}>
                <label style={{ display: 'block', fontSize: '13px', fontWeight: '600', color: '#475569', marginBottom: '6px' }}>ให้คะแนนความพึงพอใจ:</label>
                <select value={rating} onChange={(e) => setRating(Number(e.target.value))} style={{ width: '100%', padding: '10px', borderRadius: '8px', border: '1px solid #CBD5E1', fontSize: '14px' }}>
                  <option value={5}>⭐⭐⭐⭐⭐ (5 ดาว - ดีเยี่ยม)</option>
                  <option value={4}>⭐⭐⭐⭐ (4 ดาว - ดีมาก)</option>
                  <option value={3}>⭐⭐⭐ (3 ดาว - ปานกลาง)</option>
                  <option value={2}>⭐⭐ (2 ดาว - พอใช้)</option>
                  <option value={1}>⭐ (1 ดาว - ควรปรับปรุง)</option>
                </select>
              </div>

              <div style={{ marginBottom: '20px' }}>
                <label style={{ display: 'block', fontSize: '13px', fontWeight: '600', color: '#475569', marginBottom: '6px' }}>ความคิดเห็นของคุณ:</label>
                <textarea 
                  rows="4" 
                  placeholder="แชร์ประสบการณ์การใช้งานอุปกรณ์ชิ้นนี้..." 
                  value={comment}
                  onChange={(e) => setComment(e.target.value)}
                  style={{ width: '100%', padding: '10px', borderRadius: '8px', border: '1px solid #CBD5E1', fontSize: '14px', outline: 'none' }}
                  required
                />
              </div>

              <div style={{ display: 'flex', justifyContent: 'flex-end', gap: '10px' }}>
                <button type="button" onClick={() => setReviewModalOpen(false)} style={{ background: '#F1F5F9', color: '#475569', border: 'none', padding: '10px 16px', borderRadius: '8px', fontWeight: '600', cursor: 'pointer' }}>
                  ปิด
                </button>
                <button type="submit" style={{ background: '#16A34A', color: '#FFFFFF', border: 'none', padding: '10px 16px', borderRadius: '8px', fontWeight: '600', cursor: 'pointer' }}>
                  ยืนยันส่งรีวิว
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
}
